/* ============================================================================
 * UnAI Labs — ONE-PASTE BLOG BACKLOG PUBLISHER  (Sprint 63, 2026-10-03)
 * ----------------------------------------------------------------------------
 * HOW TO USE (requires a LIVE authenticated wp-admin session):
 *   1. Log in to https://unai-labs.com/wp-admin/  (tick "Remember Me").
 *   2. Open the browser DevTools Console on ANY wp-admin page.
 *   3. Paste this entire script and press Enter.
 * It publishes every staged blog post below that is NOT already live, in ONE
 * pass (seconds), so a short admin window drains the whole backlog at once.
 * IDEMPOTENT: it checks each slug first and SKIPS any that already exists, so
 * re-running it is safe and never creates duplicates. Records each new post ID.
 * ==========================================================================*/
(async () => {
  const POSTS = [{"n": 31, "title": "The Testing Effect: Why Trying to Remember Beats Reading It Again", "slug": "the-testing-effect-why-recall-beats-rereading", "category": 28, "categoryName": "AI Literacy", "excerpt": "Re-reading your notes feels like learning, but it barely moves the needle. Retrieval practice — trying to recall before you check — is one of the most reliable ways to build durable memory. Here's the science, and how to use it (with AI's help).", "contentB64": ""}, {"n": 32, "title": "The Fifth Lever: How Social Connection Protects Your Brain", "slug": "the-fifth-lever-how-social-connection-protects-your-brain", "category": 29, "categoryName": "Brain Health", "excerpt": "Sleep, movement, nutrition and stress get all the attention — but social connection is the brain-health lever most people overlook. Here's what the science actually shows, where it stops, and how to act on it without overselling it.", "contentB64": ""}, {"n": 33, "title": "The Neuroscience of Curiosity: Why Wanting to Know Makes You Learn Better", "slug": "the-neuroscience-of-curiosity", "category": 17, "categoryName": "Neuroplasticity", "excerpt": "Curiosity isn't just a nice feeling — when you genuinely want to know something, your brain seems to prime itself to remember. Here's what the science actually shows, where it stops, and how to use AI to widen your curiosity instead of killing it.", "contentB64": ""}, {"n": 34, "title": "Hearing Loss and Cognitive Decline: What the Science Actually Shows (and Where It Stops)", "slug": "hearing-loss-and-cognitive-decline-what-the-science-shows", "category": 29, "categoryName": "Brain Health", "excerpt": "Hearing loss is the single largest modifiable risk factor for dementia in the Lancet Commission's list — but a landmark trial complicates the story. Here's what the science really shows, where it stops, and what's worth doing anyway.", "contentB64": ""}, {"n": 35, "title": "How Emotion Shapes What You Remember (and Why Your Most Vivid Memories Can Still Be Wrong)", "slug": "how-emotion-shapes-what-you-remember", "category": 17, "categoryName": "Neuroplasticity", "excerpt": "Emotion is one of the strongest forces deciding what sticks in memory and what fades — but the same feeling that burns an event in can also distort it. Here's the real science of emotion and memory, and how to use it to learn on purpose.", "contentB64": ""}];
  const api = (window.wpApiSettings && wpApiSettings.root) || '/wp-json/';
  // Fresh nonce: prefer wpApiSettings, else fetch one from admin-ajax.
  let nonce = (window.wpApiSettings && wpApiSettings.nonce) || null;
  if (!nonce) {
    try { nonce = (await (await fetch('/wp-admin/admin-ajax.php?action=rest-nonce')).text()).trim(); } catch(e){}
  }
  if (!nonce || nonce === '0') { console.error('NOT AUTHENTICATED — log in first (no valid REST nonce).'); return; }
  const H = { 'Content-Type':'application/json', 'X-WP-Nonce': nonce };
  const dec = b64 => decodeURIComponent(escape(atob(b64)));
  const results = [];
  for (const p of POSTS) {
    try {
      const existing = await (await fetch(`${api}wp/v2/posts?slug=${p.slug}&status=publish,draft,pending,future,private&_fields=id,slug`, {headers:{'X-WP-Nonce':nonce}})).json();
      if (Array.isArray(existing) && existing.length) {
        results.push({post:p.n, slug:p.slug, action:'SKIP (already exists)', id:existing[0].id});
        console.log(`SKIP post ${p.n} — slug "${p.slug}" already exists as id ${existing[0].id}`);
        continue;
      }
      const resp = await fetch(`${api}wp/v2/posts`, { method:'POST', headers:H, body: JSON.stringify({
        title: p.title, slug: p.slug, status:'publish', categories:[p.category],
        excerpt: p.excerpt, content: dec(p.contentB64)
      })});
      const j = await resp.json();
      if (resp.ok && j.id) {
        results.push({post:p.n, slug:p.slug, action:'PUBLISHED', id:j.id, cat:p.categoryName});
        console.log(`PUBLISHED post ${p.n} → id ${j.id}  (${p.categoryName})  ${j.link||''}`);
      } else {
        results.push({post:p.n, slug:p.slug, action:'ERROR', status:resp.status, code:j.code, msg:j.message});
        console.error(`ERROR post ${p.n} (${resp.status}): ${j.code} ${j.message}`);
        if (j.code === 'rest_cookie_invalid_nonce') { console.warn('Nonce expired — reload a wp-admin page to refresh wpApiSettings.nonce, then re-run (SKIP protects already-published posts).'); break; }
      }
    } catch(e) { results.push({post:p.n, slug:p.slug, action:'EXCEPTION', err:String(e)}); console.error(`EXCEPTION post ${p.n}:`, e); }
  }
  console.log('=== BATCH PUBLISH SUMMARY ===');
  console.table(results);
  console.log('Record the PUBLISHED ids in SPRINT_LOG.md. Expected pillars after all 5: Neuroplasticity 13 / AI Literacy 12 / Brain Health 12.');
  return results;
})();
